static void cil_reset_classpermission(struct cil_classpermission *cp) /* <=== cil_reset_classpermission */ 
{
	if (cp == NULL) {
		return;
	}

	cil_list_destroy(&cp->classperms, CIL_FALSE);
}

static inline void cil_reset_classperms_list(struct cil_list *cp_list) /* <=== cil_reset_classperms_list */ 
{
	struct cil_list_item *curr;

	if (cp_list == NULL) {
		return;
	}

	cil_list_for_each(curr, cp_list) {
		if (curr->flavor == CIL_CLASSPERMS) { /* KERNEL or MAP */
			cil_reset_classperms(curr->data);
		} else if (curr->flavor == CIL_CLASSPERMS_SET) { /* SET */
			cil_reset_classperms_set(curr->data);
		}
	}
}

void cil_list_destroy(struct cil_list **list, unsigned destroy_data) /* <=== cil_list_destroy */ 
{
	if (*list == NULL) {
		return;
	}

	struct cil_list_item *item = (*list)->head;
	struct cil_list_item *next = NULL;
	while (item != NULL)
	{
		next = item->next;
		if (item->flavor == CIL_LIST) {
			cil_list_destroy((struct cil_list**)&(item->data), destroy_data);
			free(item);
		} else {
			cil_list_item_destroy(&item, destroy_data);
		}
		item = next;
	}
	free(*list);
	*list = NULL;
}

static void cil_reset_classperms_set(struct cil_classperms_set *cp_set) /* <=== cil_reset_classperms_set */ 
{
	cil_reset_classpermission(cp_set->set);
}

static inline void cil_reset_classperms(struct cil_classperms *cp) /* <=== cil_reset_classperms */ 
{
	if (cp == NULL) {
		return;
	}

	cil_list_destroy(&cp->perms, CIL_FALSE);
}

void cil_list_destroy(struct cil_list **list, unsigned destroy_data) /* <=== cil_list_destroy */ 
{
	if (*list == NULL) {
		return;
	}

	struct cil_list_item *item = (*list)->head;
	struct cil_list_item *next = NULL;
	while (item != NULL)
	{
		next = item->next;
		if (item->flavor == CIL_LIST) {
			cil_list_destroy((struct cil_list**)&(item->data), destroy_data);
			free(item);
		} else {
			cil_list_item_destroy(&item, destroy_data);
		}
		item = next;
	}
	free(*list);
	*list = NULL;
}

void cil_list_item_destroy(struct cil_list_item **item, unsigned destroy_data) /* <=== cil_list_item_destroy */ 
{
	if (destroy_data) {
		cil_destroy_data(&(*item)->data, (*item)->flavor);
	}
	free(*item);
	*item = NULL;
}

